3	import org.springframework.stereotype.Component;
4	import org.springframework.transaction.annotation.Propagation;
5	import org.springframework.transaction.annotation.Transactional;
6	
7	import java.util.HashMap;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.stream.LongStream;
11	
12	/**
13	 * Takes the row locks a Transfer needs on the two Accounts it moves money between.
14	 *
15	 * <p>The one operation the {@code accounts} slice exports for {@code transfers}, and what
16	 * {@link AccountRepository} staying package-private buys: the repository's own read and
17	 * write methods belong to this package's endpoints, so from outside it there is no way to
18	 * reach a balance except through this class, and no way to take the locks in an order
19	 * other than the one {@link #inLockOrder} imposes.
20	 *
21	 * <p>Nothing here reaches past the database. That is a requirement rather than an
22	 * observation — a transaction holding these locks must never wait on a slow provider —
23	 * and it is why design decision 4 fetches the Exchange Rate in a phase of its own, before
24	 * any of this runs. {@code LockedPathTouchesOnlyTheDatabaseTest} holds the line.
25	 */
26	@Component
27	public class AccountLocking {
28	
29		private final AccountRepository accounts;
30	
31		AccountLocking(AccountRepository accounts) {
32			this.accounts = accounts;
33		}
34	
35		/**
36		 * Locks both Accounts for the rest of the caller's transaction and hands them back by
37		 * role. The caller is expected to read the source's Available Balance and write both
38		 * rows afterwards, all of it inside that same transaction.
39		 *
40		 * <p>Mandatory propagation rather than an assumption: a pessimistic lock outside a
41		 * transaction would be released before the balance it guards had been checked, and a
42		 * missing {@code @Transactional} on the caller is the kind of mistake that produces a
43		 * suite that passes and a race in production.
44		 *
45		 * @throws UnknownAccountException  if either ID has no row
46		 * @throws IllegalArgumentException if both IDs are the same Account
47		 */
48		@Transactional(propagation = Propagation.MANDATORY)
49		public LockedAccounts lockForTransfer(long sourceAccountId, long destinationAccountId) {
50			if (sourceAccountId == destinationAccountId) {
51				throw new IllegalArgumentException(
52						"account " + sourceAccountId + " cannot be both sides of a transfer");
53			}
54	
55			Map<Long, Account> locked = new HashMap<>();
56			for (long accountId : inLockOrder(sourceAccountId, destinationAccountId)) {
57				locked.put(accountId, lockForUpdate(accountId));
58			}
59			return new LockedAccounts(locked.get(sourceAccountId), locked.get(destinationAccountId));
60		}
61	
62		/**
63		 * Ascending Account ID, never the roles the Transfer gives the two.
64		 *
65		 * <p>This is the deadlock the ordering exists to prevent: were locks taken by role,
66		 * a Transfer 5 → 9 would hold 5 and want 9 while a simultaneous 9 → 5 held 9 and
67		 * wanted 5, and neither could give way. Ascending order makes both contend for 5
68		 * first, so the loser waits holding nothing. There is no cycle to form, which makes
69		 * deadlock structurally impossible rather than merely unlikely — design decision 6.
70		 *
71		 * <p>Any total order over the IDs would do; ascending is the one that reads in a log.
72		 */
73		private static List<Long> inLockOrder(long sourceAccountId, long destinationAccountId) {
74			return LongStream.of(sourceAccountId, destinationAccountId).sorted().boxed().toList();
75		}
76	
77		private Account lockForUpdate(long accountId) {
78			return accounts.findAndLockById(accountId)
79					.orElseThrow(() -> new UnknownAccountException(accountId));
80		}
81	}
