3	import hu.bankmonitor.payments.accounts.InsufficientFundsException;
4	import hu.bankmonitor.payments.common.Money;
5	import hu.bankmonitor.payments.transfers.checks.CheckLedger;
6	import org.junit.jupiter.api.BeforeEach;
7	import org.junit.jupiter.api.DisplayName;
8	import org.junit.jupiter.api.Test;
9	import org.springframework.beans.factory.annotation.Autowired;
10	import org.springframework.dao.DataIntegrityViolationException;
11	import org.springframework.transaction.IllegalTransactionStateException;
12	
13	import static hu.bankmonitor.payments.common.Currency.EUR;
14	import static org.assertj.core.api.Assertions.assertThat;
15	import static org.assertj.core.api.Assertions.assertThatThrownBy;
16	
17	/**
18	 * That a Transfer and the Check Ledger it will be settled against are written together, or
19	 * neither is.
20	 *
21	 * <p>The failure this is aimed at is quiet rather than loud. A ledger opened <em>after</em>
22	 * the Transfer's transaction commits, or skipped on some second path that creates a
23	 * Transfer, leaves a {@code PENDING} row with an empty ledger — and an empty ledger has no
24	 * outstanding Check to answer, so nothing settles it, nothing rejects it, and the support
25	 * question "why is this stuck" has no answer to find. The funds stay reserved until a person
26	 * notices.
27	 *
28	 * <p>Two of the three claims here are structural rather than behavioural: {@link
29	 * CheckLedger#openFor} refuses to run outside a transaction, and {@code
30	 * NothingButTheReservationCreatesATransferTest} holds that there is no second path. What is
31	 * left for a booted test is that the one path writes what it should.
32	 *
33	 * <p>Rows come back in SQL rather than through the entities for {@link ReservationScenario}'s
34	 * reason: a round trip through the mapping under test would agree with itself whatever it
35	 * wrote.
36	 */
37	class EveryTransferOpensItsCheckLedgerTest extends ReservationScenario {
38	
39		private static final long SOURCE = 1L;
40		private static final long DESTINATION = 2L;
41		private static final long OPENING_BALANCE = 250_00L;
42	
43		@Autowired
44		private CheckLedger ledger;
45	
46		@BeforeEach
47		void openBothAccounts() {
48			openAccount(SOURCE, OPENING_BALANCE, EUR);
49			openAccount(DESTINATION, 0L, EUR);
50		}
51	
52		@Test
53		@DisplayName("requesting a Transfer opens one outstanding row per required Check")
54		void opensOneOutstandingRowPerRequiredCheck() {
55			Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
56	
57			assertThat(checkLedgerRows())
58					.allSatisfy(row -> {
59						assertThat(row).containsEntry("TRANSFER_ID", requested.getId());
60						assertThat(row).containsEntry("VERDICT", null);
61					})
62					.extracting(row -> row.get("REQUIRED_CHECK"))
63					.containsExactlyInAnyOrder("FRAUD", "MANUAL_APPROVAL");
64		}
65	
66		/**
67		 * The two Transfers get a ledger each rather than sharing one, which is the difference
68		 * between a Check Ledger and a lookup of what a Check service has ever said.
69		 */
70		@Test
71		@DisplayName("a second Transfer gets a ledger of its own")
72		void opensASeparateLedgerForEachTransfer() {
73			Transfer first = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
74			Transfer second = reservation.reserve(transferOf(30_00L, SOURCE, DESTINATION));
75	
76			assertThat(checkLedgerRows())
77					.hasSize(4)
78					.extracting(row -> row.get("TRANSFER_ID"))
79					.containsOnly(first.getId(), second.getId());
80		}
81	
82		@Test
83		@DisplayName("a refused Transfer leaves no ledger behind either")
84		void writesNoLedgerWhenTheTransferIsRefused() {
85			assertThatThrownBy(() -> reservation.reserve(transferOf(OPENING_BALANCE + 1, SOURCE, DESTINATION)))
86					.isInstanceOf(InsufficientFundsException.class);
87	
88			assertThat(transferRows()).isEmpty();
89			assertThat(checkLedgerRows()).isEmpty();
90		}
91	
92		/**
93		 * Mandatory propagation asserted directly, rather than inferred from the fact that the
94		 * one caller happens to be transactional. It is what stops the next caller — ticket 20's
95		 * settlement, a fixture, a script — from opening a ledger that commits separately from
96		 * the Transfer it belongs to.
97		 */
98		@Test
99		@DisplayName("a ledger cannot be opened outside a transaction")
100		void refusesToOpenALedgerWithNoTransaction() {
101			Money euro = new Money(10_00L, EUR);
102			Transfer unwritten = new Transfer(SOURCE, DESTINATION, euro, euro, REQUESTED_AT);
103	
104			assertThatThrownBy(() -> ledger.openFor(unwritten))
105					.isInstanceOf(IllegalTransactionStateException.class);
106	
107			assertThat(checkLedgerRows()).isEmpty();
108		}
109	
110		/**
111		 * The check constraint doing its job, and not merely being present. {@code
112		 * V4__check_ledger.sql} allows a null Verdict beside an {@code = any (array[…])} list,
113		 * and the migration README records that the obvious way to write such a list is broken
114		 * on H2 in a way that fails <em>every</em> insert. The tests above would catch that half;
115		 * this catches the other, where the constraint accepts everything instead.
116		 *
117		 * <p>An update rather than an insert, and not incidentally: an insert of a bad Verdict
118		 * for a Check the Transfer already has is refused by the uniqueness rule below before the
119		 * constraint under test is ever consulted, which is a green test proving the wrong thing.
120		 * It is also the shape ticket 20 will write a Verdict in.
121		 */
122		@Test
123		@DisplayName("the table refuses a Verdict that is not one of the two")
124		void refusesAVerdictTheDomainDoesNotHave() {
125			reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
126	
127			assertThatThrownBy(() -> database.update("UPDATE check_ledger SET verdict = 'MAYBE'"))
128					.isInstanceOf(DataIntegrityViolationException.class);
129		}
130	
131		/**
132		 * One row per Check per Transfer, enforced where a Check service's retry will actually
133		 * hit it. Ticket 20 makes at-least-once delivery safe by guarding the update on the row
134		 * still being unanswered; that guard is only worth anything if a second delivery cannot
135		 * simply write a second row instead.
136		 */
137		@Test
138		@DisplayName("a Transfer cannot collect a second row for the same Check")
139		void refusesASecondRowForACheckTheTransferAlreadyHas() {
140			Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
141	
142			assertThatThrownBy(() -> database.update("""
143					INSERT INTO check_ledger (transfer_id, required_check, verdict)
144					VALUES (?, 'FRAUD', 'APPROVED')
145					""", requested.getId()))
146					.isInstanceOf(DataIntegrityViolationException.class);
147		}
148	}
