246	
247		private static List<Violation> violationsIn(HandlerMethodValidationException rejected) {
248			Stream<Violation> perParameter = rejected.getParameterValidationResults().stream()
249					.flatMap(result -> result.getResolvableErrors().stream()
250							.map(error -> new Violation(fieldOrParameterOf(error, result), messageOf(error))));
