278			StringBuilder path = new StringBuilder();
279			for (Reference step : rejected.getPath()) {
280				if (step.getPropertyName() == null) {
281					path.append('[').append(step.getIndex()).append(']');
282				}
283				else {
284					path.append(path.isEmpty() ? "" : ".").append(step.getPropertyName());
285				}
286			}
287			return path.toString();
288		}
289	
290		/**
291		 * What the field will take, said without naming a Java type. An enum lists its
292		 * constants, which is the whole of what a closed set like {@code Currency} has to say
293		 * about itself.
294		 */
295		private static String messageFor(@Nullable Class<?> target) {
296			if (target == null) {
297				return INVALID_VALUE;
298			}
299			if (target.isEnum()) {
300				return Stream.of(target.getEnumConstants())
301						.map(Object::toString)
302						.collect(Collectors.joining(", ", "must be one of: ", ""));
303			}
304			return WHOLE_NUMBER_TYPES.contains(target) ? "must be a whole number" : INVALID_VALUE;
305		}
306	
307		private static @Nullable String fieldOf(MessageSourceResolvable error) {
308			return error instanceof FieldError fieldError ? fieldError.getField() : null;
309		}
310	
311		/** A constraint on the parameter itself has no field of its own; the parameter is one. */
312		private static @Nullable String fieldOrParameterOf(MessageSourceResolvable error,
313				ParameterValidationResult result) {
314			String field = fieldOf(error);
315			return field != null ? field : result.getMethodParameter().getParameterName();
316		}
317	}
