1	package hu.bankmonitor.payments.accounts;
2	
3	import hu.bankmonitor.payments.common.Currency;
4	import hu.bankmonitor.payments.common.Money;
5	import org.junit.jupiter.api.DisplayName;
6	import org.junit.jupiter.api.Test;
7	
8	import static org.assertj.core.api.Assertions.assertThat;
9	import static org.assertj.core.api.Assertions.assertThatThrownBy;
10	import static org.assertj.core.api.InstanceOfAssertFactories.type;
11	
12	/**
13	 * Reserving against an {@link Account}: what it moves, what it refuses, and the figure it
14	 * tests against.
15	 *
16	 * <p>No database and no Spring, because none of the claims here are about either. That the
17	 * reservation reaches the table under a row lock is {@code ReservedFundsReachTheTableTest}'s,
18	 * and that two of them cannot both spend the same Available Balance is
19	 * {@code ConcurrentReservationsHoldTheBalanceTest}'s. What is decidable on one object is the
20	 * arithmetic and the refusal — and the refusal is why the check lives on the entity rather
21	 * than in the service that calls it: an Account that could be talked into reserving more than
22	 * it has would put the invariant in whichever caller remembered it.
23	 */
24	class AccountReservesAgainstItsAvailableBalanceTest {
25	
26		private static final Money OPENING_BALANCE = new Money(250_00L, Currency.EUR);
27	
28		private final Account account = new Account(OPENING_BALANCE);
29	
30		@Test
31		@DisplayName("reserving raises the Reserved Amount and moves no money")
32		void raisesTheReservedAmountAndMovesNoMoney() {
33			account.reserve(new Money(80_00L, Currency.EUR));
34	
35			assertThat(account.getBalance()).isEqualTo(OPENING_BALANCE);
36			assertThat(account.getReservedAmount()).isEqualTo(new Money(80_00L, Currency.EUR));
37			assertThat(account.getAvailableBalance()).isEqualTo(new Money(170_00L, Currency.EUR));
38		}
39	
40		/** Reservations accumulate: each in-flight Transfer holds its own part of the balance. */
41		@Test
42		@DisplayName("a second reservation is held alongside the first")
43		void holdsASecondReservationAlongsideTheFirst() {
44			account.reserve(new Money(80_00L, Currency.EUR));
45			account.reserve(new Money(30_00L, Currency.EUR));
46	
47			assertThat(account.getReservedAmount()).isEqualTo(new Money(110_00L, Currency.EUR));
48			assertThat(account.getAvailableBalance()).isEqualTo(new Money(140_00L, Currency.EUR));
49		}
50	
51		/** An Available Balance equal to the amount covers it; the refusal starts one Minor Unit later. */
52		@Test
53		@DisplayName("the whole Available Balance can be reserved, down to the last Minor Unit")
54		void reservesTheWholeAvailableBalance() {
55			account.reserve(OPENING_BALANCE);
56	
57			assertThat(account.getAvailableBalance()).isEqualTo(Money.zero(Currency.EUR));
58		}
59	
60		@Test
61		@DisplayName("a reservation larger than the Available Balance is refused")
62		void refusesToReserveMoreThanIsAvailable() {
63			Money beyondReach = new Money(250_01L, Currency.EUR);
64	
65			assertThatThrownBy(() -> account.reserve(beyondReach))
66					.asInstanceOf(type(InsufficientFundsException.class))
67					.satisfies(refused -> {
68						assertThat(refused.getAvailableBalance()).isEqualTo(OPENING_BALANCE);
69						assertThat(refused.getRequestedAmount()).isEqualTo(beyondReach);
70					});
71	
72			assertThat(account.getReservedAmount()).isEqualTo(Money.zero(Currency.EUR));
73		}
74	
75		/**
76		 * What is already reserved is spent as far as a later reservation is concerned, which is
77		 * the whole reason the check tests the Available Balance rather than the balance.
78		 */
79		@Test
80		@DisplayName("a reservation is refused against what earlier ones have already spoken for")
81		void refusesToReserveWhatIsAlreadySpokenFor() {
82			account.reserve(new Money(200_00L, Currency.EUR));
83	
84			assertThatThrownBy(() -> account.reserve(new Money(50_01L, Currency.EUR)))
85					.isInstanceOf(InsufficientFundsException.class);
86	
87			assertThat(account.getReservedAmount()).isEqualTo(new Money(200_00L, Currency.EUR));
88		}
89	
90		/**
91		 * {@link Money} refuses the comparison rather than the Account refusing the reservation:
92		 * an amount in another Currency is a caller that skipped a conversion, not a request an
93		 * Account has an answer to.
94		 */
95		@Test
96		@DisplayName("a reservation in another Currency is refused as a caller's mistake")
97		void refusesAReservationInAnotherCurrency() {
98			assertThatThrownBy(() -> account.reserve(new Money(10_00L, Currency.USD)))
99					.isInstanceOf(IllegalArgumentException.class)
100					.hasMessageContaining("EUR")
101					.hasMessageContaining("USD");
102		}
